let conns = [];

function setup() {
  createCanvas(800, 600);

  for (let i = 0; i < 10; i++) {
    conns.push(new Conn());
  }
}

function draw() {
  background(0);

  for (let c of conns) {
    c.show();
  }
}


class Conn {
  constructor() {
    this.a = createVector(random(width/8 + 10), random(10, height/2));
    this.b = createVector(random(width - width/8, width - 10), random(10, height/2));

  }

  show() {
    push();

    const f = lerp(noise(this.a.x + this.b.y + frameCount * 0.012), 0.5, 0.5); // min(1.5, max(0, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 1.5)));
    const c = createVector(this.b.x-this.a.x, 0).mult(f).rotate(1);
    stroke(128)
    noFill()
    bezier(this.a.x, this.a.y,
           this.a.x + c.x, this.a.y + c.y,
           this.b.x - c.x, this.b.y + c.y,
           this.b.x, this.b.y);

    fill(32)
    noStroke();
    circle(this.a.x, this.a.y, 20);
    circle(this.b.x, this.b.y, 20);


    pop();
  }
}
